module.exports = function(RED) {
    const sessionManager = require("../../runtime/session-manager").getInstance(RED);
    const atService = require("../../services/africastalking")(RED);

    function CallUserNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;
        this.config = RED.nodes.getNode(config.config);

        node.on('input', async function(msg) {
            try {
                const phoneNumber = msg.phoneNumber || msg.payload;
                if (!phoneNumber) {
                    node.error("Missing phoneNumber in msg");
                    return;
                }

                const flowId = node.z; // Current flow ID
                const campaignId = msg.campaignId || `camp_${Date.now()}`;

                // Create session
                const session = await sessionManager.createSession(phoneNumber, flowId, campaignId);
                await sessionManager.setWaitingNode(session.sessionId, node.id, { 
                    nextNodeId: null // Will be updated by engine
                });

                const voice = atService.getVoiceClient();

                const options = {
                    callFrom: config.callerId || node.config.defaultCallerId,
                    callTo: phoneNumber,
                    callStartUrl: `${process.env.BASE_URL || 'http://localhost:1880'}/kumva/ivr/callback`,
                    // You can also use queueUrl for more control
                };

                // Make the call
                const result = await voice.call(options);

                msg.sessionId = session.sessionId;
                msg.campaignId = campaignId;
                msg.phoneNumber = phoneNumber;
                msg.callStatus = result;

                node.send(msg);
                node.status({ fill: "green", shape: "dot", text: "Called" });

            } catch (err) {
                node.error(err.message);
                node.status({ fill: "red", shape: "ring", text: "Error" });
            }
        });
    }

    RED.nodes.registerType("call-user", CallUserNode);
};